// Busca el texto plano del mail (n8n Gmail Trigger suele traerlo en 'text' o 'snippet')
const body = $json.text || $json.snippet || $json.html || '';

// Busca la línea "LINK DE DRIVE" y la URL que sigue
const match = body.match(/LINK DE DRIVE[:\s]*\n?\s*(https?:\/\/drive\.google\.com\/\S+)/i);
const driveUrl = match ? match[1].trim() : null;

// Extrae el ID de la carpeta desde la URL (formato .../folders/<ID>...)
let folderId = null;
if (driveUrl) {
  const idMatch = driveUrl.match(/folders\/([a-zA-Z0-9_-]+)/);
  folderId = idMatch ? idMatch[1] : null;
}

return {
  json: {
    asunto: $json.subject || '',
    driveUrl,
    folderId,
    linkEncontrado: !!folderId,
  },
};

// Recibe la lista de archivos de la carpeta (un item por archivo) y arma UN solo item
// resumen con los documentos que nos importan para esta comparación. El Tercero Pagador
// y el CSSEM (Cuestionario de Salud Sin Examen Médico) son opcionales -- solo existen si
// corresponde (alguien distinto del Tomador paga la póliza / se adjuntó el cuestionario).

function buscar(items, patron) {
  const encontrado = items.find(i => patron.test(i.json.name || ''));
  return encontrado ? { fileId: encontrado.json.id, fileName: encontrado.json.name } : null;
}

const solicitud = buscar($input.all(), /solicitud/i);
const dni        = buscar($input.all(), /\bdni\b/i);
const aval       = buscar($input.all(), /\baval\b/i);
const terceroPagador = buscar($input.all(), /(tercero|3.?ro).*pagador/i);
const cssem      = buscar($input.all(), /cssem|cuestionario.*salud/i);

// Lista completa de nombres de archivo, para el chequeo de documentación (DOC) más adelante
const archivosEnCarpeta = $input.all().map(i => i.json.name);

return [{
  json: {
    solicitudEncontrada: !!solicitud,
    solicitud,
    dni,
    aval,
    terceroPagador,
    cssem,
    archivosEnCarpeta,
  },
}];

// Convierte el item resumen en hasta 5 items (uno por documento encontrado),
// para que el nodo de descarga de Drive procese cada uno. El Tercero Pagador
// y el CSSEM son opcionales -- si no están en la carpeta, no hay nada que
// descargar ni extraer.
const d = $input.first().json;
const items = [];

if (d.solicitud) items.push({ json: { tipo: 'solicitud', fileId: d.solicitud.fileId, fileName: d.solicitud.fileName } });
if (d.dni)       items.push({ json: { tipo: 'dni',       fileId: d.dni.fileId,       fileName: d.dni.fileName } });
if (d.aval)      items.push({ json: { tipo: 'aval',      fileId: d.aval.fileId,      fileName: d.aval.fileName } });
if (d.terceroPagador) items.push({ json: { tipo: 'tercero_pagador', fileId: d.terceroPagador.fileId, fileName: d.terceroPagador.fileName } });
if (d.cssem)      items.push({ json: { tipo: 'cssem',     fileId: d.cssem.fileId,     fileName: d.cssem.fileName } });

// Guardamos también la lista completa de archivos para el chequeo de documentación (DOC),
// pegada en cada item para no perderla más adelante.
for (const it of items) it.json.archivosEnCarpeta = d.archivosEnCarpeta;

return items;

// El microservicio (extractor/service/app.py) ya soporta los 3 tipos
// (solicitud, aval, dni -- ver extract_solicitud.py / extract_aval.py /
// extract_dni.py). Si igual llega un error acá (con 'continueOnFail'
// activado en el nodo HTTP) es una falla real -- PDF corrupto, timeout,
// servicio caído, etc. -- y corta el workflow en vez de taparla con datos
// de prueba.
//
// Para tipo='solicitud' el servicio también corre el motor de
// completitud (check_completitud.py, devuelve 'incompletos') y el de
// consistencia interna (check_consistencia.py, devuelve
// 'inconsistencias') -- los guardamos aparte de 'campos' para que
// 'Consolidar y Chequear' los pueda usar directo.

const original = $('Descargar Archivo').item.json;
const tipo = original.tipo;
const respuesta = $json;

if (respuesta.error) {
  throw new Error(`Error llamando al microservicio extractor para '${tipo}' (${original.fileName}): ${JSON.stringify(respuesta.error)}`);
}

return {
  json: {
    ...original,
    datosExtraidos: respuesta.campos,
    datosIncompletos: respuesta.incompletos || [],
    datosInconsistencias: respuesta.inconsistencias || [],
  },
};

// Junta los items sueltos (solicitud/dni/aval/tercero_pagador) en un solo
// objeto y corre las validaciones. Implementadas: completitud de la
// SOLICITUD (Bloques 0 a 14, vía check_completitud.py en el
// microservicio), consistencia interna de la SOLICITUD (checkboxes
// contradictorios, % de beneficiarios, montos vs límites -- vía
// check_consistencia.py en el microservicio), consistencia cruzada de
// fecha de nacimiento + nombre + N° de documento (SOLICITUD vs DNI) y
// CUIT + nombre (SOLICITUD vs AVAL), consistencia SOLICITUD vs Tercero
// Pagador (N° de Solicitud + nombre del Tomador), regla CSSEM (si la
// Pregunta 7 declara una consulta/examen médico reciente dentro de los 3
// meses de la Fecha de solicitud, avisa que se van a pedir los análisis),
// reglas de negocio PEP/Sujeto Obligado UIF por profesión (Tomador Y
// Pagador), y un checklist DOC best-effort (busca por nombre de archivo en
// la carpeta, no valida contenido ni a quién pertenece cada documento).

const porTipo = {};
for (const item of $input.all()) {
  porTipo[item.json.tipo] = item.json.datosExtraidos;
}
const solicitudItem = $input.all().find((i) => i.json.tipo === 'solicitud');
const incompletosSolicitud = (solicitudItem && solicitudItem.json.datosIncompletos) || [];
const inconsistenciasSolicitud = (solicitudItem && solicitudItem.json.datosInconsistencias) || [];
const archivosEnCarpeta = $input.first().json.archivosEnCarpeta || [];

const errores = [...inconsistenciasSolicitud];
const incompletos = [...incompletosSolicitud];
const docsFaltantes = [];
const reglasImportantes = [];

const solicitud = porTipo.solicitud || {};
const dni = porTipo.dni || {};
const aval = porTipo.aval || {};
const terceroPagador = porTipo.tercero_pagador || null;
const cssem = porTipo.cssem || null;

function normalizar(s) {
  return (s || '')
    .toString()
    .toUpperCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '') // saca acentos
    .replace(/\s+/g, ' ')
    .trim();
}

function soloDigitos(s) {
  return (s || '').toString().replace(/\D/g, '');
}

// Compara por palabra (no por igualdad exacta de string) porque cada
// documento trae el nombre completo en distinto orden/formato (ej. la
// Solicitud trae "Apellido Nombre" en un solo campo, el DNI/AVAL lo traen
// separado o en otro orden).
function palabrasQueFaltan(nombreDeReferencia, nombreAComparar) {
  const palabrasRef = normalizar(nombreDeReferencia).split(' ');
  const palabrasComparar = normalizar(nombreAComparar).split(' ').filter(Boolean);
  return palabrasComparar.filter((p) => !palabrasRef.includes(p));
}

function mismoNombre(nombreA, nombreB) {
  if (!nombreA || !nombreB) return false;
  return palabrasQueFaltan(nombreA, nombreB).length === 0 && palabrasQueFaltan(nombreB, nombreA).length === 0;
}

// extract_dni.py devuelve la fecha como "10 NOV 1977" (OCR del frente del
// DNI); extract_solicitud.py la devuelve como "09/12/1989". Hay que pasar
// una al formato de la otra antes de comparar.
const MESES_ES = {
  ENE: '01', FEB: '02', MAR: '03', ABR: '04', MAY: '05', JUN: '06',
  JUL: '07', AGO: '08', SEP: '09', OCT: '10', NOV: '11', DIC: '12',
};

function fechaDniAFormatoSolicitud(fechaDni) {
  if (!fechaDni) return null;
  const partes = fechaDni.trim().split(/\s+/);
  if (partes.length < 3) return null;
  const [dia, mesTexto, anio] = partes;
  const mes = MESES_ES[mesTexto.toUpperCase()];
  if (!mes || !/^\d{1,2}$/.test(dia) || !/^\d{4}$/.test(anio)) return null;
  return `${dia.padStart(2, '0')}/${mes}/${anio}`;
}

const nombreSolicitud = solicitud['SOLICITANTE / TOMADOR - Nombre y Apellido'];
const fechaNacSolicitud = solicitud['SOLICITANTE / TOMADOR - Fecha de nacimiento'];
const dniSolicitud = solicitud['SOLICITANTE / TOMADOR - DNI / LC / LE'];
const cuitSolicitud = solicitud['SOLICITANTE / TOMADOR - CUIT / CUIL / CDI'];
const apellidoDni = dni['DNI - Apellido'];
const nombreDni = dni['DNI - Nombre'];
const fechaNacDni = dni['DNI - Fecha de nacimiento'];
const documentoDni = dni['DNI - Documento N°'];
const nombreDniCompleto = `${apellidoDni || ''} ${nombreDni || ''}`.trim();

// --- Regla: fecha de nacimiento SOLICITUD vs DNI ---
if (fechaNacSolicitud && fechaNacDni) {
  const fechaDniConvertida = fechaDniAFormatoSolicitud(fechaNacDni);
  if (!fechaDniConvertida) {
    incompletos.push(
      `No se pudo interpretar la fecha de nacimiento del DNI ("${fechaNacDni}") para compararla contra la Solicitud.`
    );
  } else if (fechaDniConvertida !== fechaNacSolicitud) {
    errores.push(
      `Fecha de nacimiento no coincide: Solicitud dice ${fechaNacSolicitud}, ` +
      `DNI dice ${fechaNacDni} (${fechaDniConvertida}).`
    );
  }
}

// --- Regla: nombre y apellido SOLICITUD vs DNI ---
if (nombreSolicitud && nombreDniCompleto) {
  const faltantes = palabrasQueFaltan(nombreSolicitud, nombreDniCompleto);
  if (faltantes.length > 0) {
    errores.push(
      `Nombre no coincide: Solicitud dice "${nombreSolicitud}", DNI dice ` +
      `"${nombreDniCompleto}" (no aparece en la Solicitud: ${faltantes.join(', ')}).`
    );
  }
}

// --- Regla: N° de documento SOLICITUD vs DNI ---
if (dniSolicitud && documentoDni) {
  if (soloDigitos(dniSolicitud) !== soloDigitos(documentoDni)) {
    errores.push(
      `N° de documento no coincide: Solicitud dice ${dniSolicitud}, DNI dice ${documentoDni}.`
    );
  }
}

// --- Regla: CUIT y nombre SOLICITUD vs AVAL ---
// El único AVAL de prueba disponible es una constancia de Monotributo de
// ARCA a nombre del propio Solicitante (no de un tercero garante) -- por
// eso se compara contra "Solicitante/Tomador", no contra un campo
// "garante" separado (la Solicitud no tiene uno). Si en la práctica
// aparece un AVAL de otro tipo (garantía de un tercero), esta regla hay
// que revisarla.
const cuitAval = aval['AVAL - CUIT'];
if (cuitSolicitud && cuitAval) {
  if (soloDigitos(cuitSolicitud) !== soloDigitos(cuitAval)) {
    errores.push(
      `CUIT no coincide: Solicitud dice ${cuitSolicitud}, AVAL dice ${cuitAval}.`
    );
  }
}

const nombreAval = aval['AVAL - Nombre y Apellido / Razón Social'];
if (nombreSolicitud && nombreAval) {
  const faltantes = palabrasQueFaltan(nombreSolicitud, nombreAval);
  if (faltantes.length > 0) {
    errores.push(
      `Nombre no coincide: Solicitud dice "${nombreSolicitud}", AVAL dice ` +
      `"${nombreAval}" (no aparece en la Solicitud: ${faltantes.join(', ')}).`
    );
  }
}

// --- Regla: SOLICITUD vs Tercero Pagador (si existe el formulario) ---
if (terceroPagador) {
  const solicitudNroPagador = terceroPagador['N° de Solicitud'];
  const solicitudNroPropia = solicitud['N° de Solicitud / Póliza'];
  if (solicitudNroPagador && solicitudNroPropia && solicitudNroPagador !== solicitudNroPropia) {
    errores.push(
      `N° de Solicitud no coincide entre la Solicitud (${solicitudNroPropia}) y el formulario de ` +
      `Tercero Pagador (${solicitudNroPagador}).`
    );
  }
  const nombreTomadorPagador = terceroPagador['Nombre del Tomador'];
  if (nombreTomadorPagador && nombreSolicitud && !mismoNombre(nombreSolicitud, nombreTomadorPagador)) {
    errores.push(
      `Nombre del Tomador no coincide entre la Solicitud ("${nombreSolicitud}") y el formulario de ` +
      `Tercero Pagador ("${nombreTomadorPagador}").`
    );
  }
}

// --- Regla: CSSEM (Cuestionario de Salud Sin Examen Médico) -- Pregunta 7,
// consulta/examen médico reciente (definida por Bells Group, 2026-08-05) ---
// Si la Pregunta 7 del CSSEM ("¿Ha consultado a un médico...? / ¿ha sido
// sometido a algún examen o investigación médica...?") está marcada "Sí" y
// la fecha declarada cae DENTRO de los 3 meses de la Fecha de solicitud,
// avisar que Zurich va a solicitar los análisis correspondientes. Si fue
// hecho hace MÁS de 3 meses, puede no pedirlos -- no hace falta avisar.
function parseFechaFlexible(str) {
  if (!str) return null;
  const partes = str.trim().split('/');
  if (partes.length === 2) {
    const [mm, yyyy] = partes;
    if (!/^\d{1,2}$/.test(mm) || !/^\d{4}$/.test(yyyy)) return null;
    return { dia: 1, mes: parseInt(mm, 10), anio: parseInt(yyyy, 10) };
  }
  if (partes.length === 3) {
    const [dd, mm, yyyy] = partes;
    if (!/^\d{1,2}$/.test(dd) || !/^\d{1,2}$/.test(mm) || !/^\d{4}$/.test(yyyy)) return null;
    return { dia: parseInt(dd, 10), mes: parseInt(mm, 10), anio: parseInt(yyyy, 10) };
  }
  return null;
}

// Compara por FECHA EXACTA (fecha del examen + 3 meses calendario, contra
// la Fecha de solicitud) en vez de restar meses calendario -- restar solo
// mes/año subestima el caso límite (ej. examen 01/03/2026 vs Solicitud
// 10/06/2026 son 3 meses Y 9 días, más de 3 meses reales, pero
// "junio - marzo = 3" los contaría igual como "dentro de los 3 meses").
function dentroDeTresMeses(fechaAnteriorStr, fechaPosteriorStr) {
  const anterior = parseFechaFlexible(fechaAnteriorStr);
  const posterior = parseFechaFlexible(fechaPosteriorStr);
  if (!anterior || !posterior) return null;
  const limite = new Date(anterior.anio, anterior.mes - 1 + 3, anterior.dia);
  const posteriorDate = new Date(posterior.anio, posterior.mes - 1, posterior.dia);
  return posteriorDate <= limite;
}

if (cssem && solicitud['Producto / Formulario'] === 'Zurich Options' && cssem['Pregunta 7 - Consulta/examen médico reciente - Sí'] === 'Marcado') {
  const fechaExamen = cssem['Pregunta 7 - Fecha'];
  const fechaSolicitudStr = solicitud['Fecha de solicitud'];
  if (!fechaExamen) {
    incompletos.push(
      'El CSSEM declara una consulta/examen médico reciente (Pregunta 7) pero no indica la fecha -- no se ' +
      'puede determinar si corresponde avisar que se van a solicitar los análisis.'
    );
  } else if (!fechaSolicitudStr) {
    incompletos.push(
      `No se pudo determinar la Fecha de solicitud para compararla contra la fecha declarada en el CSSEM ` +
      `(Pregunta 7: ${fechaExamen}).`
    );
  } else {
    const dentroDe3Meses = dentroDeTresMeses(fechaExamen, fechaSolicitudStr);
    if (dentroDe3Meses === null) {
      incompletos.push(
        `No se pudo interpretar la fecha declarada en el CSSEM (Pregunta 7: "${fechaExamen}") para compararla ` +
        `contra la Fecha de solicitud (${fechaSolicitudStr}).`
      );
    } else if (dentroDe3Meses) {
      reglasImportantes.push(
        `CSSEM Pregunta 7: declara una consulta/examen médico de ${fechaExamen}, dentro de los 3 meses de la ` +
        `Fecha de solicitud (${fechaSolicitudStr}) -- se van a solicitar los análisis correspondientes.`
      );
    }
    // Si no está dentro de los 3 meses, no hace falta avisar (Zurich puede no pedirlos).
  }
}

// --- Reglas de negocio: PEP / Sujeto Obligado UIF (definidas por Bells
// Group) ---
// Si se declara alguna de estas profesiones y la persona SÍ está marcada
// como Sujeto Obligado UIF, corresponde cargar la constancia de UIF (si
// la tiene). "CORREDOR INMOBILIARIO"/"ASESOR INMOBILIARIO" y "CONTADOR
// PUBLICO"/"CONTADOR" se tratan como el mismo caso (variantes del mismo
// nombre de profesión).
const PROFESIONES_UIF = ['CONTADOR', 'ESCRIBANO', 'PRODUCTOR DE SEGUROS', 'INMOBILIARIO'];
// Si se declara alguna de estas profesiones y la persona NO está marcada
// como Sujeto Obligado UIF, corresponde presentar la nota (plantilla que
// está en Drive) aclarando que no lo es.
const PROFESIONES_NOTA_NO_UIF = ['CONTADOR', 'ABOGADO', 'INMOBILIARIO'];

function hayArchivoQueMatchee(patron) {
  return archivosEnCarpeta.some((nombre) => patron.test(nombre || ''));
}

function profesionDispara(profesion, lista) {
  const profesionNorm = normalizar(profesion);
  return lista.some((p) => profesionNorm.includes(p));
}

// Mismas reglas de PEP/UIF por profesión, pero para una persona genérica
// (usada tanto para el Tomador como para el Pagador del formulario de
// Tercero Pagador -- ver más abajo).
function chequearUifPep(rol, profesion, esSujetoObligadoUIF, esPEP) {
  if (profesion && profesionDispara(profesion, PROFESIONES_UIF) && esSujetoObligadoUIF) {
    if (!hayArchivoQueMatchee(/uif/i)) {
      reglasImportantes.push(
        `${rol} declara profesión "${profesion}" y está marcado como Sujeto Obligado UIF -- ` +
        `verificar que la constancia de UIF esté cargada (no se encontró un archivo con "UIF" en el nombre).`
      );
    }
  }
  if (profesion && profesionDispara(profesion, PROFESIONES_NOTA_NO_UIF) && !esSujetoObligadoUIF) {
    if (!hayArchivoQueMatchee(/nota/i)) {
      reglasImportantes.push(
        `${rol} declara profesión "${profesion}" y NO está marcado como Sujeto Obligado UIF -- ` +
        `debe presentar la nota correspondiente (no se encontró un archivo con "nota" en el nombre).`
      );
    }
  }
  if (esPEP && !hayArchivoQueMatchee(/\bcof\b/i)) {
    reglasImportantes.push(
      `${rol} está declarado como PEP (Persona Expuesta Políticamente) -- debe enviarse el ` +
      'Cuestionario de Origen de Fondos (COF) y documentación respaldatoria (no se encontró un ' +
      'archivo con "COF" en el nombre).'
    );
  }
}

// Ojo: el checkbox "Sujeto Obligado ante la UIF" del Tomador es UNO SOLO
// en toda la Solicitud (declaración jurada del Solicitante/Tomador,
// Bloque 12) -- no hay un checkbox equivalente por cada Vida Asegurada.
// Para el Tomador (y para el Pagador, si hay Tercero Pagador) se puede
// cruzar profesión contra el checkbox real; para las Vidas Aseguradas
// solo se puede avisar (no hay dato para confirmar si corresponde o no).
chequearUifPep(
  'El Tomador',
  solicitud['SOLICITANTE / TOMADOR - Actividad principal'],
  solicitud['¿Sujeto Obligado ante la UIF (Art. 20 Ley 25.246)? - Sí'] === 'Marcado',
  solicitud['¿PEP - Persona Expuesta Políticamente? - Sí'] === 'Marcado'
);

for (const rol of ['VIDA ASEGURADA 1', 'VIDA ASEGURADA 2']) {
  const profesion = solicitud[`${rol} - Profesión`];
  if (profesion && profesionDispara(profesion, PROFESIONES_UIF)) {
    reglasImportantes.push(
      `${rol} declara profesión "${profesion}" (típicamente Sujeto Obligado UIF) -- la Solicitud no trae ` +
      `un checkbox de Sujeto Obligado propio para la Vida Asegurada, verificar manualmente si corresponde ` +
      `Sujeto Obligado UIF y cargar la constancia (o la nota, si no lo es).`
    );
  }
}

// Si hay Tercero Pagador y es Persona Física, tiene sus propias
// declaraciones de Sujeto Obligado UIF / PEP en el formulario -- se
// chequean igual que las del Tomador. Si es Persona Jurídica, el
// formulario no declara una profesión individual (es una empresa), así
// que esta regla no aplica ahí -- pero si la empresa (o alguno de los
// socios del Anexo 1) resultara Sujeto Obligado o PEP, hoy no hay forma
// automática de saberlo.
if (terceroPagador && terceroPagador['Pagador - Tipo'] === 'Física') {
  chequearUifPep(
    'El Pagador (Tercero Pagador)',
    terceroPagador['PAGADOR - Profesión'],
    terceroPagador['Pagador - ¿Sujeto Obligado ante la UIF? - Sí'] === 'Marcado',
    terceroPagador['Pagador - ¿PEP? - Sí'] === 'Marcado'
  );
}

// --- Checklist DOC (definido por Bells Group) ---
// Best-effort: busca por PATRÓN DE NOMBRE DE ARCHIVO en la carpeta, no
// valida el contenido de cada documento ni a qué persona pertenece (hoy
// "Clasificar Archivos" toma como mucho 1 DNI y 1 AVAL por carpeta, no
// uno por persona) -- en escenarios con más de un DNI/AVAL requerido
// (Tomador ≠ Vida Asegurada, Tercero Pagador) solo se puede confirmar que
// ALGÚN archivo de ese tipo está, no que estén los de todas las personas
// involucradas. Eso queda marcado explícitamente como "verificar
// manualmente" en vez de darlo por bueno.
const producto = solicitud['Producto / Formulario'];
const tomadorEsVida = mismoNombre(nombreSolicitud, solicitud['VIDA ASEGURADA 1 - Nombre y Apellido']);
const tomadorEsPagador = solicitud['Titular medio de pago = Solicitante - Sí'] === 'Marcado';
const pagaConCbu = solicitud['Medio de pago - CBU'] === 'Marcado';

if (!hayArchivoQueMatchee(/\bdni\b/i)) docsFaltantes.push('DNI');
if (!hayArchivoQueMatchee(/\baval\b/i)) docsFaltantes.push('AVAL (comprobante de domicilio)');
if (pagaConCbu && !hayArchivoQueMatchee(/cbu/i)) {
  docsFaltantes.push('Constancia de CBU (el medio de pago declarado es CBU)');
}

// Tercero Pagador: aplica a AMBAS familias, no solo Invest Future -- Bells
// Group solo describió este escenario para Invest Future, pero un
// ejemplo real (Zurich Options-AECLIF-1354029) confirma que también pasa
// en Options (Tercero Pagador Persona Jurídica). Se chequea siempre que
// el medio de pago no esté a nombre del Tomador, sea cual sea el producto.
if (!tomadorEsPagador) {
  if (!terceroPagador) {
    docsFaltantes.push(
      'El pago no está a nombre del Tomador (hay un Tercero Pagador) -- falta el formulario "Solicitud ' +
      'de 3ro Pagador" en la carpeta de Drive (no se encontró un archivo que matchee "tercero"/"3ro" + ' +
      '"pagador" en el nombre).'
    );
  } else if (terceroPagador['Pagador - Tipo'] === 'Jurídica') {
    docsFaltantes.push(
      `Tercero Pagador Persona Jurídica (${terceroPagador['PAGADOR - Razón Social'] || '(sin Razón Social)'}) ` +
      '-- verificar que estén cargados: DNI y AVAL de los socios del Anexo 1, Estatuto social actualizado, ' +
      'Actas de designación de autoridades/representantes/apoderados, y registro de acciones (titularidad ' +
      'del capital social). El chequeo automático no puede confirmar estos documentos por nombre de archivo.'
    );
  } else if (terceroPagador['Pagador - Tipo'] === 'Física') {
    docsFaltantes.push(
      `Tercero Pagador Persona Física (${terceroPagador['PAGADOR - Nombre y Apellido'] || '(sin nombre)'}) ` +
      '-- verificar que estén cargados DNI y AVAL de domicilio del Tercero Pagador (el chequeo automático ' +
      'solo confirma que existe 1 archivo de cada tipo en la carpeta, no que sea el del Tercero Pagador).'
    );
  } else {
    docsFaltantes.push(
      'AVISO: el pago no está a nombre del Tomador (hay un Tercero Pagador) y no se pudo determinar si ' +
      'el formulario "Solicitud de 3ro Pagador" corresponde a una persona física o jurídica -- revisar ' +
      'manualmente.'
    );
  }
}

if (producto === 'Zurich Options') {
  // CSSEM (Cuestionario de Salud sin Examen Médico): la Solicitud Options
  // no trae un campo Sí/No de "conforme/no conforme" con la declaración
  // de salud -- no hay forma de determinar automáticamente si corresponde,
  // queda para revisión manual del Productor. CSSEM es EXCLUSIVO de
  // Options (confirmado por Bells Group, 2026-08-05) -- Invest Future
  // NUNCA lo requiere, sin importar la Declaración de Salud.
  reglasImportantes.push(
    'Verificar manualmente si corresponde CSSEM (Cuestionario de Salud sin Examen Médico) -- la ' +
    'Solicitud Options no trae un campo que indique esto.'
  );
} else if (producto === 'Zurich Invest Future') {
  if (tomadorEsPagador && !tomadorEsVida) {
    docsFaltantes.push(
      'AVISO: el Tomador es distinto de la Vida Asegurada -- verificar manualmente que estén cargados ' +
      'DNI y AVAL de AMBOS (el chequeo automático solo confirma que existe 1 archivo de cada tipo en ' +
      'la carpeta, no que haya uno por persona).'
    );
  }
}

return [{
  json: {
    cliente: nombreSolicitud || nombreDniCompleto || '(sin identificar)',
    errores,
    incompletos,
    docsFaltantes,
    reglasImportantes,
  },
}];

const d = $input.first().json;

function seccion(titulo, lista) {
  if (!lista.length) return `${titulo}: sin novedades.`;
  return `${titulo}:\n` + lista.map(x => ` - ${x}`).join('\n');
}

const cuerpo = [
  `Informe de revisión — ${d.cliente}`,
  '',
  seccion('Errores del formulario', d.errores),
  '',
  seccion('Información incompleta', d.incompletos),
  '',
  seccion('Documentación faltante en el Drive', d.docsFaltantes),
  '',
  seccion('Reglas importantes a revisar', d.reglasImportantes),
].join('\n');

return [{
  json: {
    asuntoInforme: `Revisión de negocio — ${d.cliente}`,
    cuerpoInforme: cuerpo,
  },
}];
